const FIELDS=new Map(RAW.split('\n').map(s=>{const p=s.split('|');return [Number(p[0]),p]}));
const TEXT=new Map(PRINT.split('\n').map(s=>{const p=s.split('|');return [Number(p[0]),p]}));
